def audit(event: str, **fields):
    STATE.mkdir(parents=True, exist_ok=True)
    with AUDIT.open("a", encoding="utf-8") as h:
        h.write(
            json.dumps(
                {"at_utc": now(), "event": event, **fields, "production_touched": False},
