            )
            + "\n"
        )


def age_seconds(path: Path) -> float | None:
    try:
        raw = path.read_text(encoding="utf-8").strip().replace("Z", "+00:00")
        dt = datetime.fromisoformat(raw)
        return max(0.0, time.time() - dt.timestamp())
    except Exception:
        return None


def is_production_environment() -> bool:
