def capability_catalog() -> list[dict[str, Any]]:
    """Return read-only declarative metadata for all registered semantic capabilities."""
    items: list[dict[str, Any]] = []
    for code in registered_capabilities():
        cap = _CAPABILITIES[code]
        meta = _CAPABILITY_METADATA.get(code, {})
        details = _capability_contract_details(cap.code, meta)
        rule = (
            "|".join(sorted(_PYTEST_CERTIFICATION_SUITES))
            if cap.code == "WORKER_PYTEST_CERTIFICATION_READONLY"
            else meta.get("bounded_context_rule", "CAPABILITY_OWNED")
        )
        items.append(
            {
                "code": cap.code,
                "modes": list(cap.modes),
                "bounded_context_rule": rule,
                "allowed_constraints": list(
                    meta.get("allowed_constraints", ())
                ),
                "allowed_path_roots": list(
                    meta.get("allowed_path_roots", ())
                ),
                "bounded_context_path_ownership": {
                    context: sorted(paths)
                    for context, paths in (
                        meta.get("bounded_context_path_ownership", {}) or {}
                    ).items()
                },
                "raw_worker_fields_forbidden": True,
                **details,
            }
        )
    return items


